   /** Apply one effect of a resolving item. Records whether it changed anything observable, which is what a following `reflexive` ("when you do", CR 603.12) asks. */
   async applyEffect(item: StackItem, e: Effect, idx: number, all: Effect[]) {
     const mark = this.changes;
     await this.applyEffectCore(item, e, idx, all);
-    this.lastHappened = this.changes !== mark;
+    // CR 603.12: a clause the parser could not read did not *happen*. `case 'unknown'` (and the `default` branch for
+    // an op no family handles) emits an `unsimulated` event, which `emit` counts in `this.changes` like any other —
+    // so without this guard a reflexive behind an unparsed effect fires for free, which is strictly worse than not
+    // firing. Reporting a gap must never read as an action.
+    this.lastHappened = e.op !== 'unknown' && this.changes !== mark;
   }

